create stream test_stb_sxny_cn_sbgjpt_index_drzfdl_v4 trigger force_window_close  watermark 15m into ctg_res_db.test_stb_sxny_cn_sbgjpt_index_drzfdl_v4 tags(point varchar(50),index_code varchar(50),country_equipment_code varchar(50),ps_code varchar(50),ps_name varchar(50)) subtable(concat('test_stb_sxny_cn_sbgjpt_index_drzfdl_v4_',index_code,'_',point,'_',country_equipment_code)) as select  _wstart dt  ,first(val) fir_val  ,last(val) sec_val from ctg_tsdb.stb_sxny_cn where index_code in ('drzfdl') partition by tbname, point,index_code,country_equipment_code,ps_code,'山东庆云关家三峡储能电站' as ps_name interval(1d);
create stream str_tb_station_power_info trigger  at_once ignore expired 0 fill_history 1 into ctg_res_db.stb_station_power_info tags(company varchar(255),ps_name varchar(255),country_code varchar(255),ps_code varchar(255),rated_energy varchar(255),rated_power_unit varchar(255),data_unit varchar(255),remark varchar(255)) subtable(concat('station_power_info_',ps_code)) as select  today() ts ,t.rated_power ,t.minimum_power ,t.data_rate from ctg_tsdb.tb_station_power_info t partition by tbname,t.company,t.ps_name,t.country_code,t.ps_code,t.rated_energy,t.rated_power_unit,t.data_unit,t.remark ; 
create stream str_sxny_cn_sbgjpt_stationmsg_cnstationstatus_bj1 trigger force_window_close watermark 15m  into ctg_res_db.stb_sxny_cn_sbgjpt_stationmsg_cnstationstatus_bj1 tags(point varchar(50),ps_code varchar(255),cnstationno varchar(255),index_code varchar(50)) subtable(concat('stationmsg_cnstationstatus_bj1_',point)) as   select  _wstart ts,last(val) val   from ctg_tsdb.stb_sxny_cn   where  index_code in ('jldlglyjbj','zldlglyjbj','jydzyjyxbj','krqttcqbj','dyyjyxbj','dcdtwdyjyxbj','dcdtdyyjyxbj','dyyjyxbj','cd_dljcyjyxbj','fd_dljcyjyxbj') and ts >=today() and dcc_flag='1' partition by tbname point,ps_code,cnstationno,index_code interval(15m) fill(prev);
create stream str_hbny_sx_mint_jzzt2 trigger force_window_close watermark 5m into ctg_res_db.stb_hbny_sx_mint_jzzt2 tags(senid varchar(255),sen_name varchar(255),index_code varchar(255),jz_location varchar(255),jz_no varchar(255), ps_name varchar(255),ps_code varchar(255)) subtable(concat('cjdl_rtdb_jzzt','_',senid))as select _wstart ts,last(v) from ctg_tsdb.stb_hbny_sx_mint where ps_code in ('0511','0512','0513') partition by tbname,senid,sen_name,index_code,jz_location,jz_no,ps_name,ps_code interval(10m) fill(prev) ;
create stream stm_dwi_sxny_snestation_data_power trigger  force_window_close watermark 5m into ctg_res_db.stb_dwi_sxny_snestation_data_power tags(ps_code varchar(50),ps_name  varchar(50),province_name varchar(50),area_name varchar(50),company_name varchar(50),ps_type  varchar(50)) subtable(concat('stb_dwi_cjdl_rtems_power','_',ps_code)) as select _wstart ts, avg(ftotalp) val from ctg_tsdb.stb_sxny_snestation_data where 1=1 and ts >= today() -1d and ps_name is not null partition by tbname, ps_code,ps_name,province_name,area_name,company_name,ps_type interval(5m);
create stream stm_dwi_hbny_sx_mint_power trigger force_window_close watermark 5m into ctg_res_db.stb_dwi_hbny_sx_mint_power tags(ps_code varchar(50),  ps_name  varchar(50), province_name varchar(50), area_name varchar(50), company_name varchar(50),  ps_type  varchar(50), index_seq varchar(50)) subtable(concat('stb_dwi_cjdl_rtems_power','_',ps_code)) as select _wstart ts, avg(v) val from ctg_tsdb.stb_hbny_sx_mint where index_code ='czyggl' and ts >= today() -1d partition by tbname,ps_code,ps_name,province_name,area_name,company_name,ps_type,index_seq interval(5m) fill(prev); 
create stream stm_dwi_cjdl_rtems_power trigger force_window_close watermark 5m  into ctg_res_db.stb_dwi_cjdl_rtems_power  tags(ps_code varchar(50),  ps_name  varchar(50),  province_name varchar(50), area_name varchar(50),  company_name varchar(50), ps_type  varchar(50),  index_seq varchar(50) ) subtable(concat('stb_dwi_cjdl_rtems_power','_',ps_code)) as select _wstart ts, avg(factv) val from ctg_tsdb.stb_cjdl_rtems  where index_code = 'czyggl' and ts >= today() - 1d partition by tbname, ps_code, ps_name,province_name, area_name, company_name, ps_type,index_seq interval(5m) fill(prev);
create stream stm_dwi_hbny_sx_mint_unit_power trigger force_window_close watermark 5m into ctg_res_db.stb_dwi_hbny_sx_mint_unit_power tags(sen_name varchar(50),ps_code varchar(50),ps_name  varchar(50),province_name varchar(50),area_name varchar(50),company_name varchar(50),ps_type  varchar(50)) subtable(concat('dwi_hbny_sx_mint_power','_',ps_code)) as select _wstart ts, avg(v) val from ctg_tsdb.stb_hbny_sx_mint t where 1=1 and t.index_code = 'jzyggl' and t.ts >= today() -1d partition by tbname,sen_name,ps_code,ps_name,province_name,area_name,company_name,ps_type interval(5m) fill(prev);
create stream stm_dwi_cjdl_rtems_unit_power trigger force_window_close watermark 5m into ctg_res_db.stb_dwi_cjdl_rtems_unit_power tags(sen_name  varchar(50),ps_code varchar(50),ps_name  varchar(50),province_name varchar(50),area_name varchar(50),company_name varchar(50),ps_type  varchar(50)) subtable(concat('stb_dwi_cjdl_rtems_power','_',sen_name)) as select _wstart ts, avg(factv) val from ctg_tsdb.stb_cjdl_rtems where index_code = 'jzyggl' and ts >= today() -1d partition by tbname,sen_name,ps_code,ps_name,province_name,area_name,company_name,ps_type interval(5m) fill(prev);
create stream str_stb_sxny_cn_all_cz_yggl_base trigger  force_window_close watermark 5m into ctg_res_db.stb_sxny_cn_all_cz_yggl_base tags(ps_code varchar(255),cnstationno varchar(255)) subtable(concat('yggl_base_',ps_code)) as select  ts ,sum(val) val from ctg_tsdb.stb_sxny_cn_all_cz_yggl_base1 partition by tbname,ts,ps_code,cnstationno interval(15m) fill(prev);
create stream str_stb_sxny_cn_all_cz_yggl_base1 trigger  force_window_close watermark 15m into ctg_res_db.stb_sxny_cn_all_cz_yggl_base1 tags(ps_code varchar(255),cnstationno varchar(255)) subtable(concat('yggl_base1_',point)) as select  _wstart ts ,last(val) val  from ctg_tsdb.stb_sxny_cn where cz_flag = '1' and index_code = 'yggl' and ts >= today() partition by tbname,point,ps_code,cnstationno interval(15m);
create stream str_sxny_cn_sbgjpt_stationmsg_cnstationstatus_bj trigger   force_window_close watermark 5m into ctg_res_db.stb_sxny_cn_sbgjpt_stationmsg_cnstationstatus_bj tags(ps_code varchar(255),cnstationno varchar(255)) subtable(concat('stationmsg_cnstationstatus_bj_',ps_code)) as select last(ts) ts, avg(val) val from ctg_tsdb.stb_sxny_cn_sbgjpt_stationmsg_cnstationstatus_bj1 where 1=1 partition by tbname,ps_code,cnstationno  interval(5m);
create stream str_cjdl_rtdb_jzzt2 trigger force_window_close watermark 5m into ctg_res_db.stb_cjdl_rtdb_jzzt2 tags( point_code varchar(255), point_name varchar(255), index_code varchar(255), jz_location varchar(255), jz_no varchar(255), ps_name varchar(255), ps_code varchar(255)) subtable(concat('cjdl_rtdb_jzzt','_',point_code))as select _wstart, last(factv) factv from ctg_tsdb.stb_cjdl_rtdb partition by tbname,point_code,point_name,index_code,jz_location,jz_no,ps_name,ps_code interval(10m) fill(prev);
create stream stb_sxny_cn_sbgjpt_index_blq_yjbj trigger window_close watermark 5m ignore expired 0 fill_history 1 into ctg_res_db.stb_sxny_cn_sbgjpt_index_blq_yjbj tags(point varchar(50),index_code varchar(50),country_equipment_code varchar(50)) subtable(concat('stb_sxny_cn_sbgjpt_index_blq_yjbj_',index_code,'_',point,'_',country_equipment_code)) as select  today() - 1d ts ,_wstart dt ,to_char(_wstart,'yyyy-mm-dd') stat_date ,first(ts) fir_dt ,last(ts) sec_dt ,cast(val as integer) val from ctg_tsdb.stb_sxny_cn where index_code in ('jldlglyjbj','zldlglyjbj','jydzyjyxbj') and ts >= today() - 1 partition by tbname,to_char(ts,'yyyy-mm-dd') as stat_date,index_code,point,country_equipment_code,'03X4' as ps_code,'山东庆云关家三峡储能电站' as ps_name state_window(cast(val as integer));
create stream stm_sxny_cn_power_all_cz_yggl trigger force_window_close watermark 15m into ctg_res_db.stb_sxny_cn_all_cz_yggl tags(point  varchar(50),ps_code varchar(50),cnstationno  varchar(50)) subtable(concat('sxny_cn_all_cz_yggl','_',point)) as select _wstart ts,avg(val) val from ctg_tsdb.stb_sxny_cn where cz_flag='1' and index_code='yggl' partition by tbname,point,ps_code,cnstationno interval(15m);
